# Verify no top-level imports in any file
for f in ['crucible_hidden/test_m1.py', 'crucible_hidden/test_m2.py', 'crucible_hidden/test_m3.py']:
    with open(f) as fh:
        content = fh.read()

    lines = content.split('\n')
    in_function = False
    top_level_imports = []
    for i, line in enumerate(lines):
        stripped = line.strip()
        if stripped.startswith('def test_'):
            in_function = True
        elif not in_function and (stripped.startswith('import ') or stripped.startswith('from ')):
            top_level_imports.append((i+1, stripped))

    if top_level_imports:
        print(f"{f}: TOP-LEVEL IMPORTS FOUND!")
        for lineno, imp in top_level_imports:
            print(f"  Line {lineno}: {imp}")
    else:
        print(f"{f}: No top-level imports ✓")
